UPDATE products SET short_description = '**Wood-pressed** groundnut oil, rich in Vitamin E and natural nutty flavour.', benefits = '[\"Naturally rich in Vitamin E\",\"Heart-friendly monounsaturated fats\",\"Free from trans fats\",\"Good source of Omega-6 fatty acids\"]', benefits_text = 'Natural nutty aroma and authentic groundnut taste\nHigh smoke point, stays stable for deep frying\nDesi groundnuts sourced directly from farmers', how_to_use = 'Ideal for everyday cooking, including sabzi, dal tadka, puri, pakode, frying, sautéing, roasting, and traditional Indian recipes.' WHERE handle = 'groundnut-oil';
UPDATE products SET short_description = '**Wood-pressed** yellow mustard oil with Omega-3 and a mild, balanced aroma.', benefits = '[\"Rich in Omega-3 and Omega-6 fatty acids\",\"Heart-friendly unsaturated fats\",\"Good source of MUFA\",\"Low in saturated fat\"]', benefits_text = 'Natural mustard aroma, milder than black mustard\nBright golden colour\nTraditionally keeps achaar fresh for longer', how_to_use = 'Gently heat the oil until it begins to smoke, then reduce the heat slightly before adding spices. Ideal for tadka, sautéing, frying, and traditional Indian cooking.' WHERE handle = 'yellow-mustard-oil';
UPDATE products SET short_description = '**Wood-pressed** black mustard oil with a bold, pungent kachi ghani taste.', benefits = '[\"Rich in Omega-3 and essential fatty acids\",\"Supports healthy circulation in cold weather\",\"Natural pungent compounds give its sharp kick\",\"A warming oil, traditional in winter\"]', benefits_text = 'Bold aroma and a stronger taste than yellow mustard\nDarker colour from black mustard seeds\nTraditional choice for winter body massage\nNo added flavour or colour', how_to_use = 'Heat to smoking point, then lower the flame before adding spices; this mellows the raw pungency. Ideal for achaar, tadka, sabzi and Bengali-style cooking.' WHERE handle = 'black-mustard-oil';
UPDATE products SET short_description = '**Wood-pressed** black til oil for massage, hair care and daily wellness.', benefits = '[\"Black til, the most valued til for wellness\",\"Natural antioxidants sesamol and sesamin\",\"Deeply nourishes dry hair and scalp\",\"Jet-black sesame seeds from Gujarat\"]', benefits_text = 'Traditionally used for abhyanga (self-massage)\nUsed for oil pulling (gandusha)\nThicker and darker than other til oils', how_to_use = 'Warm slightly and massage into skin or scalp. Leave on for 30 minutes before bathing.' WHERE handle = 'black-sesame-oil';
UPDATE products SET short_description = '**Wood-pressed** white til oil from Marwar, light and nutty for daily cooking.', benefits = '[\"Good fats for a healthy heart\",\"Natural antioxidant sesamin\",\"Light and easy for everyday meals\",\"Desi white sesame from Marwar, Rajasthan\"]', benefits_text = 'Light, mild til flavour\nClear, light colour\nAlso used traditionally for body massage', how_to_use = 'Ideal for everyday cooking, South Indian dishes, chutneys, tadka and salad dressings.' WHERE handle = 'white-sesame-oil';
UPDATE products SET short_description = '**Wood-pressed** brown til oil with a warm aroma for cooking and pickles.', benefits = '[\"Rich in sesamol, which keeps the oil naturally stable\",\"Good source of Vitamin E\",\"A warming oil, ideal in winter\",\"Desi brown sesame from farmers in Marwar, Rajasthan\"]', benefits_text = 'Warm, toasty til aroma\nDeeper flavour than white til oil\nA traditional choice for winter body massage', how_to_use = 'Use for daily cooking, pickles, chutneys and til-based sweets. For massage, warm slightly and apply.' WHERE handle = 'brown-sesame-oil';
UPDATE products SET short_description = '**Wood-pressed** alsi oil, a natural plant source of Omega-3. Best used raw.', benefits = '[\"Natural plant source of Omega-3 (ALA)\",\"Supports heart health\",\"Supports healthy digestion\",\"Nourishes hair and scalp\"]', benefits_text = 'Fresh, nutty and slightly earthy taste\nSlow wood pressing protects its delicate Omega-3\nA natural vegetarian alternative to fish oil', how_to_use = 'Take 1 teaspoon a day, or drizzle over salads, raita and roti after cooking. Do not heat or fry. Refrigerate after opening.' WHERE handle = 'flaxseed-oil';
UPDATE products SET short_description = '**Wood-pressed** sulphur-free coconut oil for cooking, hair and skin.', benefits = '[\"Naturally rich in medium-chain fatty acids (MCTs)\",\"Contains lauric acid\",\"Nourishes hair and moisturises skin\",\"Sulphur-free coconuts from Tiptur, Karnataka\"]', benefits_text = 'Rich natural coconut aroma and flavour\nTurns solid in winter, a sign of pure coconut oil\nA favourite for traditional baby malish', how_to_use = 'Use for South Indian cooking, sautéing and baking. For hair and skin, warm slightly and massage gently. If it has set in winter, keep the bottle in warm water for a few minutes.' WHERE handle = 'coconut-oil';
UPDATE products SET short_description = '**Wood-pressed** sunflower oil, light and heart-friendly for everyday cooking.', benefits = '[\"Heart-friendly, rich in natural antioxidants\",\"Rich in MUFA, PUFA and Omega-6\",\"Helps maintain healthy cholesterol\",\"Natural source of Vitamin E\"]', benefits_text = 'Light, mild taste that lets the food\'s own flavour come through\nClean, pale golden finish\nSuits the whole family, from kids to elders', how_to_use = 'Use for everyday sabzi, dal, parathas, sautéing and baking. Its light taste suits both Indian and continental dishes.' WHERE handle = 'sunflower-oil';
UPDATE products SET short_description = '**Wood-pressed** badam rogan for hair, skin and gentle baby massage.', benefits = '[\"Packed with Vitamin E for hair and skin\",\"Rich in healthy monounsaturated fats\",\"Nourishes hair, skin and scalp\",\"Supports overall health and wellbeing\"]', benefits_text = 'Light, non-sticky texture that absorbs easily\nGentle enough for baby massage\nMild, natural almond aroma', how_to_use = 'Massage a few drops into skin or scalp. For babies, warm slightly and massage gently.' WHERE handle = 'almond-oil';
UPDATE products SET short_description = '**Wood-pressed** akhrot oil for wellness and skin care.', benefits = '[\"Plant source of Omega-3 (ALA)\",\"Natural antioxidants\",\"Nourishes skin and hair\",\"Supports overall wellness\"]', benefits_text = 'Rich, nutty aroma\nLight golden colour\nPressed in small batches from quality walnuts', how_to_use = 'Massage a few drops into skin or scalp, or drizzle over salads and finished dishes. Do not heat.' WHERE handle = 'walnut-oil';
UPDATE products SET short_description = '**Wood-pressed** arandi oil for hair, dry skin and joint massage.', benefits = '[\"Rich in ricinoleic acid\",\"Nourishes hair, brows and lashes\",\"Soothes dry, rough skin\",\"Traditional for joint massage\"]', benefits_text = 'Thick, rich texture\nPure and unrefined, nothing added\nFor external use only', how_to_use = 'Warm slightly and massage into scalp, dry skin or joints. Leave on for an hour or overnight, then wash. For brows and lashes, apply a little with a clean brush at night.' WHERE handle = 'castor-oil';
UPDATE products SET short_description = 'Dark, slightly tangy honey from jamun blossoms.', benefits = '[\"Raw and unheated\",\"Less sweet, with a tangy finish\",\"Dark, mineral-rich honey\",\"Natural enzymes intact\"]', benefits_text = 'Collected from jamun blossoms in season\nThick, dark texture\nCrystallises over time; warm the jar gently to soften', how_to_use = 'Take with warm (not hot) water, or use on toast and desserts. Do not cook at high heat.' WHERE handle = 'jamun-raw-honey';
UPDATE products SET short_description = 'Wild honey from the Sunderban mangroves.', benefits = '[\"Wild honey from the Sunderban mangroves\",\"Raw and unprocessed, straight from wild hives\",\"Naturally multi-floral\",\"Natural antioxidants intact\"]', benefits_text = 'Flavour changes naturally with the season\'s wild flowers\nColour varies from light to amber by harvest\nNo added sugar or syrup', how_to_use = 'Take a spoon with warm (not hot) water in the morning, or add to tea, toast and desserts. Do not cook at high heat.' WHERE handle = 'sunderban-raw-honey';
UPDATE products SET short_description = 'Raw honey from tulsi-rich forest areas.', benefits = '[\"Raw honey from tulsi-rich forests\",\"Light herbal notes of tulsi\",\"Never pasteurised\",\"Pollen and enzymes left intact\"]', benefits_text = 'Collected from forest bee colonies\nLight, smooth sweetness\nMay crystallise in cold weather, which is natural', how_to_use = 'Take a spoon with warm (not hot) water in the morning, or add to tea and kadha once it has cooled a little. Do not cook at high heat.' WHERE handle = 'van-tulsi-raw-honey';
UPDATE products SET short_description = 'Unrefined sugarcane sweetener, the old-fashioned way.', benefits = '[\"Unrefined, no bleaching\",\"Keeps the natural minerals of sugarcane\",\"Sulphur-free\",\"Mild caramel taste\"]', benefits_text = 'Made the old-fashioned way from sugarcane juice\nFree-flowing, light brown grains\nNo preservatives or additives', how_to_use = 'Use in place of white sugar, in the same quantity, in tea, coffee, milk, desserts and sweets.' WHERE handle = 'desi-khand';
UPDATE products SET short_description = 'Easy-to-use gud powder for tea and sweets.', benefits = '[\"Rich natural source of iron\",\"Dissolves instantly\",\"Made without chemicals or bleach\",\"Earthy molasses taste\"]', benefits_text = 'Fine, free-flowing powder\nNo grating or breaking a block\nMade from pure sugarcane juice', how_to_use = 'Stir into tea, milk or kadha, or use in laddoo, halwa and desserts in place of sugar.' WHERE handle = 'jaggery-powder';
UPDATE products SET short_description = 'Traditional gud bhheli for everyday sweetness.', benefits = '[\"Traditional solid gud bhheli\",\"A traditional digestive after meals\",\"Free from sulphur and chemicals\",\"Rich, earthy taste of fresh sugarcane\"]', benefits_text = 'Made the old-fashioned way in open pans\nKeeps well for months when stored dry', how_to_use = 'Enjoy a small piece after meals, or melt into laddoo, chikki, halwa and kadha.' WHERE handle = 'jaggery-block';
UPDATE products SET description_html = '<p>Our **Wood Pressed Coconut Oil** is made from carefully selected, organically sourced, sulphur-free coconuts from Tiptur, Karnataka. The coconuts are processed using a traditional Kolhu wood-pressed machine, where the oil is slowly extracted to preserve its natural aroma, rich coconut flavour and goodness.</p><p>The oil is cloth-filtered and left for **natural gravity sedimentation for 10 days,** allowing heavier particles to settle naturally without aggressive filtration or chemical processing.</p><p>With its naturally rich coconut aroma and authentic flavour, it\'s perfect for traditional Indian cooking, sautéing, baking, and everyday skin and hair care.</p>' WHERE handle = 'coconut-oil';
UPDATE products SET status = 'draft' WHERE handle = 'jaggery-block';
