UPDATE settings SET value = '{\"oil\":{\"reels\":[{\"video\":\"https://res.cloudinary.com/bmqxsylj/video/upload/swadeshi-mahadev/videos/reels/ghani-2.mp4\",\"caption\":\"Slow pressing, no heat\"},{\"video\":\"https://res.cloudinary.com/bmqxsylj/video/upload/swadeshi-mahadev/videos/reels/oil-pour.mp4\",\"caption\":\"Golden oil, straight from the press\"},{\"video\":\"https://res.cloudinary.com/bmqxsylj/video/upload/swadeshi-mahadev/videos/reels/ghani-3.mp4\",\"caption\":\"Settled, filtered, bottled by hand\"},{\"video\":\"https://res.cloudinary.com/bmqxsylj/video/upload/swadeshi-mahadev/videos/reels/bottling.mp4\",\"caption\":\"Filtered and filled, batch by batch\"},{\"video\":\"https://res.cloudinary.com/bmqxsylj/video/upload/swadeshi-mahadev/videos/reels/ghani-pour.mp4\",\"caption\":\"Golden oil from the ghani\"},{\"video\":\"https://res.cloudinary.com/bmqxsylj/video/upload/swadeshi-mahadev/videos/reels/ghani-1.mp4\",\"caption\":\"Seeds going into the ghani\"}],\"checks\":{\"intro\":\"Four simple checks. Unrefined oil behaves a little differently, and that\'s a good sign.\",\"items\":[{\"body\":\"Open the cap. Kachi ghani oil smells strongly of the seed it came from.\",\"icon\":\"smell\",\"image\":\"/images/product-story/check-smell-v1.webp\",\"title\":\"Smell it\"},{\"body\":\"Keep a little in the fridge. Unrefined oil may turn cloudy or thicken, and clears again at room temperature.\",\"icon\":\"cold\",\"image\":\"/images/product-story/check-cold-v1.webp\",\"title\":\"The fridge check\"},{\"body\":\"A thin layer of natural sediment can settle in the bottle. It comes from the seed, not a defect.\",\"icon\":\"look\",\"image\":\"/images/product-story/check-sediment-v1.webp\",\"title\":\"Look at the bottom\"},{\"body\":\"Traditionally wood-pressed oil is thicker and richer than refined oil, because nothing is stripped out.\",\"icon\":\"pour\",\"image\":\"/images/product-story/check-thick-v1.webp\",\"title\":\"Naturally thick, rich in texture\"}],\"title\":\"Know real kachi ghani oil at home\",\"eyebrow\":\"घर पर पहचानें\"},\"method\":{\"intro\":\"Six slow steps, the same way oil was made in village ghanis.\",\"steps\":[{\"body\":\"We start with whole, clean seeds from trusted farms.\",\"image\":\"/illustrations/process/1-farm.webp\",\"title\":\"Farm sourced\"},{\"body\":\"Stones, dust and husk are picked out before pressing.\",\"image\":\"/illustrations/process/2-hand-cleaned.webp\",\"title\":\"Hand cleaned\"},{\"body\":\"Kolhu wood pressed slowly in our kachi ghani, so the oil stays cool.\",\"image\":\"/illustrations/process/3-wood-pressed.webp\",\"title\":\"Wood pressed\"},{\"body\":\"Filtered through pure cotton cloth to catch the seed bits.\",\"image\":\"/illustrations/process/4-cloth-filtered.webp\",\"title\":\"Cotton cloth filtered\"},{\"body\":\"Rested still for 10 days so the finest particles sink on their own.\",\"image\":\"/illustrations/process/4b-gravity-settled.webp\",\"title\":\"Gravity sedimentation\"},{\"body\":\"Filled in food-grade PET bottles and sealed in small batches in Bijainagar.\",\"image\":\"/illustrations/process/5-bottled.webp\",\"title\":\"Bottled fresh\"}],\"title\":\"The kachi ghani way. No shortcuts.\",\"eyebrow\":\"कच्ची घाणी की विधि\"}}}' WHERE `key` = 'pdp_story';
UPDATE settings SET value = '[{\"href\":\"https://www.instagram.com/woodpressoil.by.mahadevproduct\",\"label\":\"Instagram\"},{\"href\":\"https://www.facebook.com/share/1Cybi8gVQE/\",\"label\":\"Facebook\"},{\"href\":\"https://youtube.com/@taksahabvlogs\",\"label\":\"YouTube\"},{\"href\":\"https://whatsapp.com/channel/0029VbBp1pa77qVWi7VElf3W\",\"label\":\"WhatsApp\"}]' WHERE `key` = 'socials';
